/**
 * Capacity policy of the store-owned decision cache: admission never treats retained families as immovable, eviction
 * only makes room for a key with proven reuse, and the aggregate budget bounds retained and in-flight bytes together.
 */
class LmdbPipelinePlanCacheCapacityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final int FAMILY_CAPACITY = 8;

	@Test
	void saturatedCacheStillAdmitsAndEvictsLeastRecentFamilyForARepeatedKey() {
		Sizes sizes = measure(Decision.UNSUPPORTED, 0);
		// Two families leave less than one transient reservation free.
		long budget = 2L * sizes.family() + sizes.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:k1"));
			assertFalse(requests.plan("urn:k2"));
			assertEquals(2, cache.entryCount());

			assertFalse(requests.plan("urn:k3"), "first miss of a new key");
			long missesBeforeRepeat = misses(cache);
			assertFalse(requests.plan("urn:k3"), "second miss of the same key");
			assertEquals(missesBeforeRepeat + 1L, misses(cache),
					"a proven repeat must own a cache flight instead of bypassing the saturated cache");
			assertTrue(requests.plan("urn:k3"), "the repeated key is published by evicting the least recent family");
			assertTrue(requests.plan("urn:k2"));
			assertFalse(requests.plan("urn:k1"), "the least recently used family was evicted");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void retainedFamiliesNeverBlockAdmissionOfAProvenRepeat() {
		Sizes sizes = measure(Decision.UNSUPPORTED, 0);
		long budget = 3L * sizes.family() + sizes.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:k1"));
			assertFalse(requests.plan("urn:k2"));
			assertFalse(requests.plan("urn:k3"));
			// Use order k2, k3, k1: k2 is now the least recently used family although k1 was published first.
			assertTrue(requests.plan("urn:k1"));
			assertTrue(cache.retainedBytes() + sizes.transientIdentity() > budget,
					"retained families leave no free room for one transient reservation");

			assertFalse(requests.plan("urn:k4"));
			assertFalse(requests.plan("urn:k4"));
			assertTrue(requests.plan("urn:k4"), "retained families must not block a proven repeat");
			assertTrue(requests.plan("urn:k1"));
			assertTrue(requests.plan("urn:k3"));
			assertFalse(requests.plan("urn:k2"), "eviction follows use recency, not publication order");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void concurrentInFlightReservationsAreBoundedAndReleasedAfterPublishOrAbandon() throws Exception {
		Sizes sizes = measure(Decision.UNSUPPORTED, 0);
		long budget = 3L * sizes.transientIdentity() + sizes.transientIdentity() / 2L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		int requests = 6;
		CountDownLatch entered = new CountDownLatch(requests);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService callers = Executors.newFixedThreadPool(requests);
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			QueryRoot failing = query("_anon_1", "urn:f0");
			AtomicLong reservedByFailingFlight = new AtomicLong();
			assertThrows(IllegalStateException.class,
					() -> cache.getOrCompute(failing, context, context::revision, () -> {
						reservedByFailingFlight.set(pendingBytes(cache));
						throw new IllegalStateException("planning failed");
					}));
			assertTrue(reservedByFailingFlight.get() > 0L, "the failing request owned a cache flight");
			assertEquals(0L, pendingBytes(cache), "an abandoned flight releases its transient reservation");
			assertInvariant(cache, budget);

			List<Future<LmdbPipelinePlanCache.Result>> results = new ArrayList<>();
			for (int index = 0; index < requests; index++) {
				QueryRoot source = query("_anon_1", "urn:c" + index);
				results.add(callers.submit(() -> cache.getOrCompute(source, context, context::revision, () -> {
					entered.countDown();
					await(release);
					return planned(source, 0);
				})));
			}
			assertTrue(entered.await(5L, TimeUnit.SECONDS), "every request plans, cached or bypassed");
			long owners = misses(cache) - 1L;
			long pending = pendingBytes(cache);
			assertTrue(owners >= 1L && owners < requests, "requests beyond the free budget bypass the cache");
			assertTrue(pending > 0L, "flights reserve their transient identities");
			assertTrue(cache.retainedBytes() + pending <= budget, "in-flight reservations are bounded");
			release.countDown();
			for (Future<LmdbPipelinePlanCache.Result> result : results) {
				result.get(5L, TimeUnit.SECONDS);
			}
			assertEquals(0L, pendingBytes(cache), "publication releases every transient reservation");
			assertEquals(owners, cache.entryCount(), "every admitted flight fits its published family");
			assertInvariant(cache, budget);
		} finally {
			release.countDown();
			callers.shutdownNow();
			cache.close();
		}
	}

	@Test
	void accountingInvariantHoldsAcrossPublishEvictAndRefresh() throws Exception {
		Sizes sizes = measure(Decision.UNSUPPORTED, 0);
		long budget = 4L * sizes.family() + 2L * sizes.transientIdentity();
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			LmdbPipelinePlanCache.Context initial = context(17L);
			LmdbPipelinePlanCache.Context revised = context(18L);
			QueryRoot first = query("_anon_1", "urn:k1");
			LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = refreshWork(first, revised);
			assertFalse(cache.getOrComputePlan(first, initial, initial::revision,
					() -> refreshable(first, refreshWork)).cacheHit());
			assertInvariant(cache, budget);
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:k2"));
			assertInvariant(cache, budget);

			QueryRoot drifted = query("_anon_2", "urn:k1");
			var refreshed = cache.getOrComputePlan(drifted, revised, revised::revision,
					() -> refreshable(drifted, refreshWork));
			assertTrue(refreshed.cacheHit());
			assertEquals("USE_AND_REFRESH",
					refreshed.plan().getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			awaitCompletedRefreshTasks(cache, 1L);
			assertEquals(0L, pendingBytes(cache), "a completed refresh releases its reservation");
			assertInvariant(cache, budget);

			for (int key = 3; key <= 9; key++) {
				for (int request = 0; request < 3; request++) {
					requests.plan("urn:k" + key);
					assertInvariant(cache, budget);
				}
				assertTrue(requests.plan("urn:k" + key), "a repeated key is cached; key=" + key);
			}
			assertTrue(decisionCache(cache).statistics().evictions() > 0L);
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void refreshedVersionsAreShrunkAndTheEntryChargeFollowsTheFamily() throws Exception {
		// A large other family: its free space also holds the refreshes' transient reservations.
		int padding = 32 * 1024;
		Sizes other = measure(query("_anon_0", "urn:kz"), Decision.UNSUPPORTED, padding);
		long refreshed;
		LmdbPipelinePlanCache measuring = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			promoteThroughRefresh(measuring);
			refreshed = measuring.retainedBytes();
		} finally {
			measuring.close();
		}
		// The refreshed family and the doorkeeper fit; another family fits only after the refreshed one sheds a tier.
		long budget = refreshed + other.family() + LmdbPlanDecisionCache.doorkeeperBytes(FAMILY_CAPACITY) - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			promoteThroughRefresh(cache);
			LmdbPlanDecisionCache decisions = decisionCache(cache);
			LmdbPlanDecisionCache.PlanVariant variant = onlyVariant(decisions);
			assertEquals("best-physical", variant.champion().physicalFingerprint());
			assertEquals(List.of("other-physical"),
					variant.challengers()
							.stream()
							.map(LmdbPlanDecisionCache.PlanVersion::physicalFingerprint)
							.toList());
			assertEquals(List.of("test-physical"), variant.rollbackVersions()
					.stream()
					.map(LmdbPlanDecisionCache.PlanVersion::physicalFingerprint)
					.toList());
			// The intervals that decided the promotion are the refreshes' own.
			assertEquals(new LmdbPlanDecisionCache.EstimatedCostInterval(0.1d, 0.1d),
					variant.champion().estimatedCostInterval());
			assertEquals(new LmdbPlanDecisionCache.EstimatedCostInterval(2.0d, 2.0d),
					variant.challengers().getFirst().estimatedCostInterval());
			for (LmdbPlanDecisionCache.PlanVersion version : versions(variant)) {
				assertEquals(LmdbCacheValueCopies.OMITTED_CACHED_DIAGNOSTIC,
						version.materialize().getStringMetricPlanned(PACKED_EXPLANATION),
						"a retained version keeps no explanation diagnostic: " + version.physicalFingerprint());
			}
			assertEquals(recomputedCharges(decisions), cache.retainedBytes(),
					"refreshed versions are charged like the published one");

			Requests requests = new Requests(cache, padding);
			assertFalse(requests.plan("urn:kz"));
			assertFalse(requests.plan("urn:kz"), "the proven repeat is published by shedding a tier");
			assertTrue(requests.plan("urn:kz"));
			LmdbPlanDecisionCache.PlanVariant shed = onlyVariant(decisions, "best-physical");
			assertTrue(shed.rollbackVersions().isEmpty(), "the published version was shed as the rollback tier");
			assertEquals(recomputedCharges(decisions), cache.retainedBytes(),
					"the entry charge follows the family after its published version is shed");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void aRankedFamilyThatCanServeNoRequestIsReclaimedAsDead() {
		long[] sizes = largest(measure(Decision.RANKED, 0), measure(Decision.UNSUPPORTED, 0));
		long budget = 2L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			// Ranked without detached refresh work: only a request at its own evidence can use it.
			assertFalse(request(cache, query("_anon_1", "urn:ks"), context(1L), 1L, Decision.RANKED));
			assertFalse(request(cache, query("_anon_1", "urn:kl"), context(2L), 1L, Decision.UNSUPPORTED));
			assertEquals(2, cache.entryCount());
			// No reader is pinned at revision 1 any more: the stale ranked family can serve no request.
			assertFalse(request(cache, query("_anon_1", "urn:kx"), context(2L), 2L, Decision.UNSUPPORTED));
			assertTrue(request(cache, query("_anon_2", "urn:kx"), context(2L), 2L, Decision.UNSUPPORTED),
					"a ranked family that can serve no request is reclaimed without proof of reuse");
			assertTrue(request(cache, query("_anon_2", "urn:kl"), context(2L), 2L, Decision.UNSUPPORTED));
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void aHardInvalidRankedFamilyIsReclaimedAsDead() {
		int padding = 32 * 1024;
		Sizes live = measure(Decision.UNSUPPORTED, padding);
		Sizes medium = measure(Decision.UNSUPPORTED, padding / 2);
		long dependentFamily;
		LmdbPipelinePlanCache measuring = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			publishDependent(measuring, padding);
			dependentFamily = measuring.retainedBytes();
		} finally {
			measuring.close();
		}
		// The dependent family, a live family and a flight fit; a further family fits only in the place of the
		// dependent one.
		long budget = dependentFamily + live.family() + LmdbPlanDecisionCache.doorkeeperBytes(FAMILY_CAPACITY)
				+ medium.transientIdentity();
		assertTrue(medium.family() > medium.transientIdentity(), "fixture needs families larger than flights");
		assertTrue(dependentFamily >= medium.family(), "fixture: reclaiming the dependent family makes room");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			publishDependent(cache, padding);
			Requests large = new Requests(cache, padding);
			assertFalse(large.plan("urn:kl"));
			assertEquals(2, cache.entryCount(), "fixture: a live family is published next to the dependent one");
			// At revision 2 the hard dependency no longer holds: the lookup invalidates the family, and the re-plan
			// (an unavailable comparison under a deadline) can never be retained, so the invalid family stays.
			QueryRoot replanned = query("_anon_2", "urn:kh");
			assertFalse(cache.getOrComputePlan(replanned, context(2L), context(2L)::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(planned(replanned, 0)),
							unavailableSummary(), null, LmdbPlanAssumptions.NONE, true),
					() -> Long.MIN_VALUE).cacheHit());
			assertEquals(2, cache.entryCount(), "fixture: the invalidated family is still resident");

			Requests requests = new Requests(cache, padding / 2);
			assertFalse(requests.plan("urn:kx"));
			assertTrue(requests.plan("urn:kx"), "a hard-invalid family is reclaimed without proof of reuse");
			assertTrue(large.plan("urn:kl"), "the live family stays");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	/** A committed-snapshot-dependent ranked decision with detached refresh work: it is invalidated, never stale. */
	private static void publishDependent(LmdbPipelinePlanCache cache, int padding) {
		QueryRoot dependent = query("_anon_1", "urn:kh");
		LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = refreshWork(dependent, context(2L));
		assertFalse(cache.getOrComputePlan(dependent, context(1L), context(1L)::revision,
				() -> new LmdbPipelinePlanCache.PlanComputation(planned(dependent, padding),
						decisionSummary("test-physical"),
						refreshWork, new LmdbPlanAssumptions(true, Set.of())),
				() -> Long.MIN_VALUE).cacheHit());
	}

	@Test
	void aTombstonedKeyNeverEvictsLiveFamilies() {
		Sizes replay = measure(Decision.REPLAY_ONLY, 0);
		long budget = 2L * replay.family() + replay.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			assertFalse(request(cache, query("_anon_1", "urn:kr"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			LmdbPlanDecisionCache decisions = decisionCache(cache);
			Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> retired = decisions
					.residentFamiliesForTest()
					.entrySet()
					.iterator()
					.next();
			LmdbPlanDecisionCache.PlanVariant variant = retired.getValue().dispatcher().variants().getFirst();
			cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(retired.getKey(),
					variant.variantId(), variant.champion().version(), true, false, 1d, 0L, true, false));
			assertFalse(request(cache, query("_anon_1", "urn:k1"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			assertFalse(request(cache, query("_anon_1", "urn:k2"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			assertTrue(request(cache, query("_anon_2", "urn:k2"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY),
					"fixture: the retired family was reclaimed for a live one");
			long evictions = decisions.statistics().evictions();

			for (int miss = 0; miss < 40; miss++) {
				assertFalse(request(cache, query("_anon_" + (miss % 10), "urn:kr"), context, Long.MIN_VALUE,
						Decision.REPLAY_ONLY), "miss=" + miss);
				assertInvariant(cache, budget);
			}
			assertEquals(evictions, decisions.statistics().evictions(),
					"a key retired under the request's evidence never evicts for a flight that cannot publish");
			assertTrue(request(cache, query("_anon_3", "urn:k1"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			assertTrue(request(cache, query("_anon_3", "urn:k2"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
		} finally {
			cache.close();
		}
	}

	@Test
	void aTombstonedKeyProvesReuseAgainOnceItsEvidenceIsNewer() {
		Sizes replay = measure(Decision.REPLAY_ONLY, 0);
		long budget = 2L * replay.family() + replay.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			assertFalse(request(cache, query("_anon_1", "urn:kr"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			LmdbPlanDecisionCache decisions = decisionCache(cache);
			Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> retired = decisions
					.residentFamiliesForTest()
					.entrySet()
					.iterator()
					.next();
			LmdbPlanDecisionCache.PlanVariant variant = retired.getValue().dispatcher().variants().getFirst();
			cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(retired.getKey(),
					variant.variantId(), variant.champion().version(), true, false, 1d, 0L, true, false));
			assertFalse(request(cache, query("_anon_1", "urn:k1"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			assertFalse(request(cache, query("_anon_1", "urn:k2"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY));
			assertTrue(request(cache, query("_anon_2", "urn:k2"), context, Long.MIN_VALUE, Decision.REPLAY_ONLY),
					"fixture: the retired family was reclaimed for a live one");
			for (int miss = 0; miss < 3; miss++) {
				assertFalse(request(cache, query("_anon_" + miss, "urn:kr"), context, Long.MIN_VALUE,
						Decision.REPLAY_ONLY), "fixture: blocked under the retiring evidence");
			}
			// Newer evidence: the full cache admits the key once it proves reuse again.
			LmdbPipelinePlanCache.Context newer = context(18L);
			boolean cached = false;
			for (int request = 0; request < 3 && !cached; request++) {
				cached = request(cache, query("_anon_v" + request, "urn:kr"), newer, Long.MIN_VALUE,
						Decision.REPLAY_ONLY);
			}
			assertTrue(cached, "the second miss under newer evidence is a proven repeat and is published");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void aKeyBlockedByAServableRankedFamilyWithRefreshWorkEvictsAtMostOnce() throws Exception {
		long[] sizes = largest(measure(Decision.UNSUPPORTED, 0), measure(Decision.RANKED, 0));
		long budget = 3L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			LmdbPipelinePlanCache.Context initial = context(17L);
			LmdbPipelinePlanCache.Context revised = context(18L);
			QueryRoot ranked = query("_anon_1", "urn:ke");
			LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = refreshWork(ranked, revised);
			assertFalse(cache.getOrComputePlan(ranked, initial, initial::revision,
					() -> refreshable(ranked, refreshWork), () -> Long.MIN_VALUE).cacheHit());
			var executorField = LmdbPlanDecisionCache.class.getDeclaredField("refreshExecutor");
			executorField.setAccessible(true);
			// No detached refresh can be submitted: requests at newer evidence re-plan on their own thread.
			((ThreadPoolExecutor) executorField.get(decisionCache(cache))).shutdownNow();
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:h1"));
			assertFalse(requests.plan("urn:h2"));
			for (int round = 0; round < 5; round++) {
				QueryRoot source = query("_anon_2", "urn:ke");
				cache.getOrComputePlan(source, revised, revised::revision,
						() -> new LmdbPipelinePlanCache.PlanComputation(planned(source, 0),
								decisionSummary("other-physical"), refreshWork),
						() -> Long.MIN_VALUE);
				requests.plan("urn:o" + round);
				assertInvariant(cache, budget);
			}
			assertTrue(decisionCache(cache).statistics().evictions() <= 1L,
					"a key blocked by a ranked family that serves stale evicts on its first proven miss only");
			QueryRoot original = query("_anon_3", "urn:ke");
			assertTrue(cache.getOrComputePlan(original, initial, initial::revision,
					() -> refreshable(original, refreshWork), () -> Long.MIN_VALUE).cacheHit(),
					"the ranked family is not displaced");
		} finally {
			cache.close();
		}
	}

	@Test
	void theDoorkeeperModelPadsItsIntArrayToEightBytes() {
		// The doorkeeper object (72), four long[capacity] (16 + 8 per slot) and one int[capacity] (16 + 4 per slot,
		// padded to 8 bytes): an odd capacity leaves 4 bytes of padding.
		for (int capacity : new int[] { 17, 18 }) {
			long intArray = (16L + 4L * capacity + 7L) / 8L * 8L;
			assertEquals(72L + 4L * (16L + 8L * capacity) + intArray, LmdbPlanDecisionCache.doorkeeperBytes(capacity),
					"capacity " + capacity);
		}
	}

	@Test
	void anAppendedAliasIsChargedItsOwnRecords() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			assertFalse(request(cache, query("_anon_1", "urn:ka"), context(17L), Long.MIN_VALUE, Decision.RANKED));
			LmdbPlanDecisionCache decisions = decisionCache(cache);
			Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> family = decisions
					.residentFamiliesForTest()
					.entrySet()
					.iterator()
					.next();
			assertEquals(recomputedCharges(decisions), cache.retainedBytes(),
					"fixture: the published family is charged its records");
			LmdbPlanDecisionCache.PlanVariant variant = family.getValue().dispatcher().variants().getFirst();
			LmdbPlanDecisionCache.ExactInvocationKey existing = family.getValue()
					.exactAliases()
					.keySet()
					.iterator()
					.next();
			LmdbPlanDecisionCache.ExactInvocationKey other = new LmdbPlanDecisionCache.ExactInvocationKey(
					family.getKey(),
					PackedPlanCache.structuralKey(query("_anon_1", "urn:kb"), LmdbCacheValueCopies.CODEC),
					existing.semanticContext());
			assertTrue(decisions.publishBuild(new LmdbPlanDecisionCache.BuildPublication(family.getKey(), other,
					family.getValue().semanticDependencies(), variant.evidenceSnapshot(), variant.evidenceSnapshot(),
					variant.champion().materialize(), variant.champion().physicalFingerprint(),
					variant.champion().estimatedCostInterval(), variant.searchCertificate(),
					LmdbPipelinePlanCache.ENTRY_OBJECT_BYTES, variant.champion().optimizerGeneration(), null)),
					"fixture: the alias is appended");
			assertEquals(2, decisions.residentFamiliesForTest().get(family.getKey()).exactAliases().size());
			assertEquals(recomputedCharges(decisions), cache.retainedBytes(),
					"an appended alias is charged its records");
		} finally {
			cache.close();
		}
	}

	@Test
	void aPublishedVariantIsChargedItsOwnRecords() throws Exception {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			promoteThroughRefresh(cache);
			LmdbPlanDecisionCache decisions = decisionCache(cache);
			Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> family = decisions
					.residentFamiliesForTest()
					.entrySet()
					.iterator()
					.next();
			LmdbPlanDecisionCache.PlanVariant champion = onlyVariant(decisions);
			TupleExpr template = query("_anon_1", "urn:kr");
			template.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			LmdbPlanDecisionCache.ApplicabilityGuard guard = new LmdbPlanDecisionCache.ApplicabilityGuard(
					new double[0], new double[0], 1L, 0L, Long.MAX_VALUE, false);
			assertTrue(decisions.publishVariant(new LmdbPlanDecisionCache.VariantPublication(family.getKey(),
					family.getValue().version(), family.getValue().semanticDependencies(),
					champion.evidenceSnapshot(), champion.evidenceSnapshot(), 7L, guard, template,
					"variant-physical", new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
					champion.searchCertificate(), champion.stabilityEnvelope(), 1024L, 1L)),
					"fixture: the variant is published");
			assertEquals(2, decisions.residentFamiliesForTest().get(family.getKey()).dispatcher().variants().size());
			assertEquals(recomputedCharges(decisions), cache.retainedBytes(),
					"a variant is charged its version and its own records");
		} finally {
			cache.close();
		}
	}

	@Test
	void oneOffMissDoesNotEvictAHotFamilyButASecondMissOfTheSameKeyDoes() {
		// Large templates: a transient reservation fits next to the hot family, the published family does not.
		int padding = 32 * 1024;
		Sizes sizes = measure(Decision.UNSUPPORTED, padding);
		assertTrue(sizes.family() > sizes.transientIdentity() + 4096L, "fixture needs families larger than flights");
		long budget = 2L * sizes.family() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, padding);
			assertFalse(requests.plan("urn:k5"));
			assertTrue(requests.plan("urn:k5"));

			assertFalse(requests.plan("urn:k6"), "a one-off miss plans");
			assertTrue(requests.plan("urn:k5"), "a one-off miss must not evict the hot family");
			assertEquals(1, cache.entryCount());

			assertFalse(requests.plan("urn:k6"), "the second miss proves reuse");
			assertTrue(requests.plan("urn:k6"), "a proven repeat is published by evicting the least recent family");
			assertFalse(requests.plan("urn:k5"));
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void alternatingKeysInABudgetForOneFamilyAreEachEventuallyCached() {
		Sizes sizes = measure(Decision.UNSUPPORTED, 0);
		// One family fits; a second key's transient reservation does not fit next to it.
		long budget = sizes.family() + sizes.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			for (int round = 0; round < 4; round++) {
				requests.plan("urn:a1");
				requests.plan("urn:b1");
				assertInvariant(cache, budget);
			}
			assertTrue(requests.plan("urn:b1"), "the last planned key was cached");
			assertFalse(requests.plan("urn:a1"));
			assertTrue(requests.plan("urn:a1"), "the other key is cached again after its own repeat");
			assertEquals(1, cache.entryCount());
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void commitThenRunLoopOnAFullCacheEndsWithTheQueryCached() {
		long[] sizes = largest(measure(Decision.RANKED, 0), measure(Decision.REPLAY_ONLY, 0));
		// Two families fill the cache: one transient reservation no longer fits next to them.
		long budget = 2L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			// Ranked families can still serve stale after a commit, so they stay live.
			assertFalse(request(cache, query("_anon_1", "urn:k1"), context(1L), Long.MIN_VALUE, Decision.RANKED));
			assertFalse(request(cache, query("_anon_1", "urn:k2"), context(1L), Long.MIN_VALUE, Decision.RANKED));
			assertEquals(2, cache.entryCount());
			for (long revision = 2L; revision <= 5L; revision++) {
				// Commit, then run Q.
				request(cache, query("_anon_1", "urn:kq"), context(revision), Long.MIN_VALUE, Decision.REPLAY_ONLY);
				assertInvariant(cache, budget);
			}
			assertTrue(request(cache, query("_anon_2", "urn:kq"), context(5L), Long.MIN_VALUE, Decision.REPLAY_ONLY),
					"a query re-run after every commit must end up cached");
		} finally {
			cache.close();
		}
	}

	@Test
	void deadReplayOnlyFamiliesAreReclaimedWithoutProofOfReuseAndDoNotAccumulate() {
		Sizes replay = measure(Decision.REPLAY_ONLY, 0);
		long budget = 2L * replay.family() + replay.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			assertFalse(request(cache, query("_anon_1", "urn:k1"), context(1L), 1L, Decision.REPLAY_ONLY));
			assertFalse(request(cache, query("_anon_1", "urn:k2"), context(1L), 1L, Decision.REPLAY_ONLY));
			assertEquals(2, cache.entryCount());
			for (long revision = 2L; revision <= 6L; revision++) {
				// No reader is pinned below the committed revision: every replay pinned to an older one is dead.
				String oneOff = "urn:x" + revision;
				assertFalse(request(cache, query("_anon_1", oneOff), context(revision), revision,
						Decision.REPLAY_ONLY));
				assertTrue(request(cache, query("_anon_2", oneOff), context(revision), revision, Decision.REPLAY_ONLY),
						"a first miss is cached when only dead replays occupy the space; revision=" + revision);
				assertInvariant(cache, budget);
			}
		} finally {
			cache.close();
		}
	}

	@Test
	void deadFamilyReclamationSparesRankedFamiliesAndReplaysAPinnedReaderCanStillHit() {
		long[] sizes = largest(measure(Decision.RANKED, 0), measure(Decision.REPLAY_ONLY, 0));
		long budget = 2L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			QueryRoot rankedSource = query("_anon_1", "urn:kr");
			LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = refreshWork(rankedSource, context(2L));
			assertFalse(cache.getOrComputePlan(rankedSource, context(1L), context(1L)::revision,
					() -> refreshable(rankedSource, refreshWork), () -> 1L).cacheHit());
			assertFalse(request(cache, query("_anon_1", "urn:kp"), context(1L), 1L, Decision.REPLAY_ONLY));
			assertEquals(2, cache.entryCount());

			// A reader is still pinned at revision 1, so the replay pinned there can still be hit.
			assertFalse(request(cache, query("_anon_1", "urn:x2"), context(2L), 1L, Decision.REPLAY_ONLY));
			assertTrue(request(cache, query("_anon_2", "urn:kp"), context(1L), 1L, Decision.REPLAY_ONLY),
					"a replay that a pinned reader can still hit is not dead");

			// The pinned reader is gone: the replay is dead; the ranked family can still serve stale.
			assertFalse(request(cache, query("_anon_1", "urn:x3"), context(2L), 2L, Decision.REPLAY_ONLY));
			assertTrue(request(cache, query("_anon_2", "urn:x3"), context(2L), 2L, Decision.REPLAY_ONLY),
					"the dead replay is reclaimed without proof of reuse");
			QueryRoot rankedAgain = query("_anon_2", "urn:kr");
			LmdbPipelinePlanCache.Result retained = cache.getOrComputePlan(rankedAgain, context(1L),
					context(1L)::revision, () -> refreshable(rankedAgain, refreshWork), () -> 2L);
			assertTrue(retained.cacheHit(), "a ranked family is never reclaimed as dead");
			assertEquals(2, cache.entryCount());
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "offset", "limit", "compare", "order", "alias", "function", "scope" })
	void queriesDifferingOnlyInANonConstantAttributeAreNotRepeats(String attribute) {
		Sizes hot = measure(Decision.UNSUPPORTED, 0);
		// The hot family fits; no further transient reservation fits next to it.
		long budget = hot.family() + hot.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:k0"));
			assertTrue(requests.plan("urn:k0"));
			LmdbPipelinePlanCache.Context context = context(17L);
			for (int variant = 0; variant < 2; variant++) {
				TupleExpr source = variant(attribute, variant);
				assertFalse(cache.getOrCompute(source, context, context::revision, () -> planned(source, 0))
						.cacheHit());
			}
			assertTrue(requests.plan("urn:k0"),
					"a query differing only in its " + attribute + " is not a repeat and must not evict");
			assertEquals(0L, decisionCache(cache).statistics().evictions());
		} finally {
			cache.close();
		}
	}

	@Test
	void languageTagCaseVariantsOfOneExactKeyProveEachOthersReuse() {
		LmdbPipelinePlanCache.Context context = context(17L);
		LmdbPipelinePlanCache unbounded = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			// Literal equality ignores the case of a language tag: both spellings are one exact key.
			QueryRoot lower = languageQuery("aa", "en");
			assertFalse(unbounded.getOrCompute(lower, context, context::revision, () -> planned(lower, 0))
					.cacheHit());
			QueryRoot upper = languageQuery("aa", "EN");
			assertTrue(unbounded.getOrCompute(upper, context, context::revision, () -> planned(upper, 0))
					.cacheHit(), "fixture: the two spellings must share one exact key");
		} finally {
			unbounded.close();
		}

		Sizes hot = measure(languageQuery("hh", "fr"), Decision.UNSUPPORTED, 0);
		// The hot family fits; no further transient reservation fits next to it.
		long budget = hot.family() + hot.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			for (int request = 0; request < 2; request++) {
				QueryRoot source = languageQuery("hh", "fr");
				assertEquals(request == 1,
						cache.getOrCompute(source, context, context::revision, () -> planned(source, 0)).cacheHit());
			}
			QueryRoot lower = languageQuery("aa", "en");
			assertFalse(cache.getOrCompute(lower, context, context::revision, () -> planned(lower, 0)).cacheHit(),
					"a first miss plans and does not evict the hot family");
			QueryRoot upper = languageQuery("aa", "EN");
			assertFalse(cache.getOrCompute(upper, context, context::revision, () -> planned(upper, 0)).cacheHit(),
					"the second miss of the same exact key proves reuse and is published");
			QueryRoot again = languageQuery("aa", "en");
			assertTrue(cache.getOrCompute(again, context, context::revision, () -> planned(again, 0)).cacheHit(),
					"equal exact keys must have equal doorkeeper fingerprints");
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void aMissWhoseDigestFailsStillPlansAndProvesNoReuse() {
		Sizes hot = measure(Decision.UNSUPPORTED, 0);
		// The hot family fits; no further transient reservation fits next to it.
		long budget = hot.family() + hot.transientIdentity() - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget, query -> {
			throw new IllegalStateException("digest failure");
		});
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:k0"));
			assertTrue(requests.plan("urn:k0"));
			for (int round = 0; round < 3; round++) {
				assertFalse(requests.plan("urn:k1"), "a request whose digest fails still plans; round=" + round);
			}
			assertTrue(requests.plan("urn:k0"), "a request without a digest never proves reuse, so it never evicts");
			assertEquals(0L, decisionCache(cache).statistics().evictions());
			assertInvariant(cache, budget);
		} finally {
			cache.close();
		}
	}

	@Test
	void aRepeatedKeyWhoseDecisionCannotBeRetainedEvictsAtMostOnce() {
		long[] sizes = largest(measure(Decision.UNSUPPORTED, 0), measure(Decision.REPLAY_ONLY, 0));
		long budget = 3L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:h1"));
			assertFalse(requests.plan("urn:h2"));
			assertFalse(requests.plan("urn:h3"));
			LmdbPipelinePlanCache.Context context = context(17L);
			for (int round = 0; round < 5; round++) {
				// An unavailable comparison planned under a wall-clock deadline is never retained.
				QueryRoot source = query("_anon_" + round, "urn:kx");
				cache.getOrComputePlan(source, context, context::revision,
						() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(source), unavailableSummary(), null,
								LmdbPlanAssumptions.NONE, true));
				requests.plan("urn:o" + round);
				assertInvariant(cache, budget);
			}
			assertTrue(decisionCache(cache).statistics().evictions() <= 1L,
					"a key that cannot publish may evict on its first proven miss only");
		} finally {
			cache.close();
		}
	}

	@Test
	void aRepeatedKeyBlockedByALiveRankedDecisionEvictsAtMostOnce() {
		long[] sizes = largest(measure(Decision.UNSUPPORTED, 0), measure(Decision.RANKED, 0));
		long budget = 3L * sizes[0] + sizes[1] - 1L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			LmdbPipelinePlanCache.Context initial = context(17L);
			// A reader pinned at an older revision: the live ranked family's evidence is current for it, so its
			// different decision is blocked. (A newer re-plan replaces a ranked family without refresh work.)
			LmdbPipelinePlanCache.Context revised = context(16L);
			assertFalse(request(cache, query("_anon_1", "urn:ke"), initial, Long.MIN_VALUE, Decision.RANKED));
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:h1"));
			assertFalse(requests.plan("urn:h2"));
			for (int round = 0; round < 5; round++) {
				assertTrue(request(cache, query("_anon_1", "urn:ke"), initial, Long.MIN_VALUE, Decision.RANKED),
						"the ranked family keeps serving its own evidence");
				// Older evidence, no detached refresh, and a different decision: the live ranked family blocks it.
				QueryRoot source = query("_anon_2", "urn:ke");
				cache.getOrComputePlan(source, revised, revised::revision,
						() -> new LmdbPipelinePlanCache.PlanComputation(planned(source, 0),
								decisionSummary("other-physical"), null));
				requests.plan("urn:o" + round);
				assertInvariant(cache, budget);
			}
			assertTrue(decisionCache(cache).statistics().evictions() <= 1L,
					"a key blocked by a live ranked family may evict on its first proven miss only");
		} finally {
			cache.close();
		}
	}

	@Test
	void anOversizedFamilyEvictsNothing() {
		int padding = 64 * 1024;
		Sizes oversized = measure(Decision.UNSUPPORTED, padding);
		// The family fits the budget but never next to the doorkeeper's charge.
		long budget = oversized.family() + LmdbPlanDecisionCache.doorkeeperBytes(FAMILY_CAPACITY) / 2L;
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, budget);
		try {
			Requests requests = new Requests(cache, 0);
			assertFalse(requests.plan("urn:h1"));
			assertFalse(requests.plan("urn:h2"));
			Requests large = new Requests(cache, padding);
			for (int round = 0; round < 4; round++) {
				assertFalse(large.plan("urn:kx"));
				assertInvariant(cache, budget);
			}
			assertEquals(0L, decisionCache(cache).statistics().evictions(), "an oversized family evicts nothing");
			assertTrue(requests.plan("urn:h1"));
			assertTrue(requests.plan("urn:h2"));
		} finally {
			cache.close();
		}
	}

	@Test
	void templateFailureAfterPlanningReleasesWaitersAndTheReservation() throws Exception {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1024 * 1024L);
		CountDownLatch ownerEntered = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(3, runnable -> {
			Thread thread = new Thread(runnable, "template-failure-test");
			thread.setDaemon(true);
			return thread;
		});
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			QueryRoot ownerSource = query("_anon_1", "urn:k1");
			Future<LmdbPipelinePlanCache.Result> owner = executor
					.submit(() -> cache.getOrCompute(ownerSource, context, context::revision, () -> {
						ownerEntered.countDown();
						await(releaseOwner);
						return new UnreadablePlan();
					}));
			assertTrue(ownerEntered.await(5L, TimeUnit.SECONDS));
			QueryRoot waiterSource = query("_anon_2", "urn:k1");
			Future<LmdbPipelinePlanCache.Result> waiter = executor.submit(() -> cache.getOrCompute(waiterSource,
					context, context::revision, () -> planned(waiterSource, 0)));
			long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
			while (cache.waits() == 0L && System.nanoTime() < deadline) {
				Thread.onSpinWait();
			}
			assertEquals(1L, cache.waits());
			releaseOwner.countDown();

			ExecutionException ownerFailure = assertThrows(ExecutionException.class,
					() -> owner.get(5L, TimeUnit.SECONDS));
			assertInstanceOf(IllegalStateException.class, ownerFailure.getCause());
			assertFalse(waiter.get(5L, TimeUnit.SECONDS).cacheHit(), "the waiter re-plans for itself");
			assertEquals(0L, pendingBytes(cache), "the failed flight returns its transient reservation");
			QueryRoot laterSource = query("_anon_3", "urn:k1");
			assertFalse(executor.submit(() -> cache.getOrCompute(laterSource, context, context::revision,
					() -> planned(laterSource, 0))).get(5L, TimeUnit.SECONDS).cacheHit());
			QueryRoot hotSource = query("_anon_4", "urn:k1");
			assertTrue(executor.submit(() -> cache.getOrCompute(hotSource, context, context::revision,
					() -> planned(hotSource, 0))).get(5L, TimeUnit.SECONDS).cacheHit(),
					"the failed flight no longer owns the key");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
			cache.close();
		}
	}

	/** A planned tree whose metrics cannot be read, so the cache fails after planning completed. */
	private static final class UnreadablePlan extends QueryRoot {
		private static final long serialVersionUID = 1L;

		@Override
		public synchronized String getStringMetricPlanned(String metricName) {
			throw new IllegalStateException("planned metrics are unreadable");
		}
	}

	private enum Decision {
		UNSUPPORTED,
		RANKED,
		REPLAY_ONLY
	}

	private static boolean request(LmdbPipelinePlanCache cache, TupleExpr source,
			LmdbPipelinePlanCache.Context context, long liveDataRevisionHorizon, Decision decision) {
		return cache.getOrComputePlan(source, context, context::revision, () -> computation(source, decision, 0),
				() -> liveDataRevisionHorizon).cacheHit();
	}

	private static LmdbPipelinePlanCache.PlanComputation computation(TupleExpr source, Decision decision,
			int padding) {
		return switch (decision) {
		case UNSUPPORTED -> LmdbPipelinePlanCache.PlanComputation.nonRefreshable(planned(source, padding));
		case RANKED -> new LmdbPipelinePlanCache.PlanComputation(planned(source, padding),
				decisionSummary("test-physical"), null);
		case REPLAY_ONLY -> new LmdbPipelinePlanCache.PlanComputation(unpriced(planned(source, padding)),
				unavailableSummary(), null);
		};
	}

	private static TupleExpr unpriced(TupleExpr plan) {
		plan.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		plan.setStringMetricPlanned("optimizer.cascadesCostComparisonCompleteness", "UNAVAILABLE_COST");
		return plan;
	}

	private static PackedPlanDecisionSummary unavailableSummary() {
		PackedPlanDecisionSummary.CostInterval interval = new PackedPlanDecisionSummary.CostInterval(Double.NaN,
				Double.NaN, Double.NaN);
		return new PackedPlanDecisionSummary("unavailable-comparison", interval,
				List.of(new PackedPlanDecisionSummary.CandidateSummary("unavailable-comparison", interval)),
				Set.of(), PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT,
				PackedPlanDecisionSummary.BoundKind.BEST_KNOWN_UNBOUNDED, Double.NaN, 0L, 0L, 0L,
				PackedPlanDecisionSummary.ComparisonCompleteness.UNAVAILABLE_COST);
	}

	/** Larger family and larger transient reservation over the measured decision kinds. */
	private static long[] largest(Sizes first, Sizes second) {
		return new long[] { Math.max(first.family(), second.family()),
				Math.max(first.transientIdentity(), second.transientIdentity()) };
	}

	private static TupleExpr variant(String attribute, int index) {
		StatementPattern pattern = new StatementPattern(Var.of("_anon_1", true),
				Var.of("predicate", VF.createIRI("urn:pg")), Var.of("object"));
		TupleExpr body = switch (attribute) {
		case "offset" -> new Slice(projection(pattern), 10L * (index + 1), 10L);
		case "limit" -> new Slice(projection(pattern), 0L, 10L + index);
		case "compare" -> projection(new Filter(pattern, new Compare(Var.of("object"),
				new ValueConstant(VF.createLiteral(5)), index == 0 ? CompareOp.LT : CompareOp.GT)));
		case "order" -> projection(new Order(pattern, new OrderElem(Var.of("object"), index == 0)));
		case "alias" -> new Projection(pattern,
				new ProjectionElemList(new ProjectionElem("object", index == 0 ? "first" : "other")));
		case "function" -> projection(new Filter(pattern, new FunctionCall(
				index == 0 ? "http://www.w3.org/2005/xpath-functions#upper-case"
						: "http://www.w3.org/2005/xpath-functions#lower-case",
				Var.of("object"))));
		case "scope" -> projection(new StatementPattern(
				index == 0 ? StatementPattern.Scope.DEFAULT_CONTEXTS : StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("_anon_1", true), Var.of("predicate", VF.createIRI("urn:pg")), Var.of("object")));
		default -> throw new IllegalArgumentException(attribute);
		};
		return new QueryRoot(body);
	}

	private static Projection projection(TupleExpr body) {
		return new Projection(body, new ProjectionElemList(new ProjectionElem("object")));
	}

	private record Sizes(long family, long transientIdentity) {
	}

	/** Sequential requests for distinct predicates of one shape; equal-length IRIs give equal modeled sizes. */
	private static final class Requests {
		private final LmdbPipelinePlanCache cache;
		private final int padding;
		private final LmdbPipelinePlanCache.Context context = context(17L);
		private int sequence;

		private Requests(LmdbPipelinePlanCache cache, int padding) {
			this.cache = cache;
			this.padding = padding;
		}

		boolean plan(String predicate) {
			QueryRoot source = query("_anon_" + (sequence++ % 10), predicate);
			return cache.getOrCompute(source, context, context::revision, () -> planned(source, padding)).cacheHit();
		}
	}

	private static final String PACKED_EXPLANATION = "optimizer.packedExplanation";

	/**
	 * Publishes a ranked family for urn:kr, then two detached refreshes through use-and-refresh: the first adds a
	 * non-dominating challenger, the second a dominating plan that is promoted, retiring the published version to the
	 * rollback tier. Every template carries an explanation diagnostic.
	 */
	private static void promoteThroughRefresh(LmdbPipelinePlanCache cache) throws Exception {
		LmdbPipelinePlanCache.Context initial = context(17L);
		LmdbPipelinePlanCache.Context challenge = context(18L);
		LmdbPipelinePlanCache.Context promote = context(19L);
		QueryRoot source = query("_anon_1", "urn:kr");
		source.setStringMetricPlanned(PACKED_EXPLANATION, "explained ".repeat(256));
		LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = promotingRefreshWork(source, challenge, promote);
		assertFalse(cache.getOrComputePlan(source, initial, initial::revision,
				() -> refreshable(source, refreshWork)).cacheHit());
		long completed = 0L;
		for (LmdbPipelinePlanCache.Context revised : List.of(challenge, promote)) {
			QueryRoot drifted = query("_anon_2", "urn:kr");
			var served = cache.getOrComputePlan(drifted, revised, revised::revision,
					() -> refreshable(drifted, refreshWork));
			assertEquals("USE_AND_REFRESH", served.plan().getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			awaitCompletedRefreshTasks(cache, ++completed);
		}
	}

	private static LmdbPlanDecisionCache.DetachedRefreshWork promotingRefreshWork(TupleExpr template,
			LmdbPipelinePlanCache.Context challenge, LmdbPipelinePlanCache.Context promote) {
		TupleExpr detached = template.clone();
		AtomicLong executions = new AtomicLong();
		return new LmdbPlanDecisionCache.DetachedRefreshWork() {
			@Override
			public LmdbPlanDecisionCache.RefreshComputation execute() {
				boolean promotion = executions.getAndIncrement() > 0L;
				TupleExpr refreshed = detached.clone();
				refreshed.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
				LmdbPlanDecisionCache.EvidenceSnapshot evidence = LmdbPipelinePlanCache
						.evidence((promotion ? promote : challenge).revision().planningRevisions());
				String physical = promotion ? "best-physical" : "other-physical";
				double cost = promotion ? 0.1d : 2.0d;
				return new LmdbPlanDecisionCache.RefreshComputation(evidence, evidence, refreshed, physical,
						new LmdbPlanDecisionCache.EstimatedCostInterval(cost, cost),
						new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
						LmdbPipelinePlanCache.certificate(decisionSummary(physical), evidence.globalEpoch()),
						LmdbPlanDecisionCache.PlanStabilityEnvelope.exact(evidence), 1024L, 1L, true, this);
			}

			@Override
			public long retainedBytes() {
				return 0L;
			}
		};
	}

	private static LmdbPlanDecisionCache.PlanVariant onlyVariant(LmdbPlanDecisionCache decisions) {
		return onlyVariant(decisions, "best-physical");
	}

	/** The single variant of the resident family whose champion has the given physical fingerprint. */
	private static LmdbPlanDecisionCache.PlanVariant onlyVariant(LmdbPlanDecisionCache decisions,
			String championFingerprint) {
		List<LmdbPlanDecisionCache.PlanVariant> matching = new ArrayList<>();
		for (LmdbPlanDecisionCache.FamilyVersion family : decisions.residentFamiliesForTest().values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : family.dispatcher().variants()) {
				if (variant.champion().physicalFingerprint().equals(championFingerprint)) {
					matching.add(variant);
				}
			}
		}
		assertEquals(1, matching.size(), "one resident variant is championed by " + championFingerprint);
		return matching.getFirst();
	}

	private static List<LmdbPlanDecisionCache.PlanVersion> versions(LmdbPlanDecisionCache.PlanVariant variant) {
		List<LmdbPlanDecisionCache.PlanVersion> versions = new ArrayList<>();
		versions.add(variant.champion());
		versions.addAll(variant.challengers());
		versions.addAll(variant.rollbackVersions());
		return versions;
	}

	/**
	 * Recomputes, independently of the stored charges, what the resident families retain: per family the entry charge
	 * less one version's records, per further variant its records, per challenger its posterior entry, per retained
	 * version its records and its refresh work's bytes, and every object the family owns (templates, semantic
	 * dependencies, family key, exact keys, refresh identities and read-log bases) once.
	 */
	private static long recomputedCharges(LmdbPlanDecisionCache decisions) {
		long total = 0L;
		for (Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> family : decisions
				.residentFamiliesForTest()
				.entrySet()) {
			FactorCostCacheKey.ProviderRetainedMemory ledger = new FactorCostCacheKey.ProviderRetainedMemory();
			long fixed = LmdbPipelinePlanCache.ENTRY_OBJECT_BYTES - LmdbPipelinePlanCache.VERSION_OBJECT_BYTES;
			Set<Long> counted = new HashSet<>();
			List<LmdbPlanDecisionCache.PlanVariant> variants = family.getValue().dispatcher().variants();
			// The entry charge covers one variant's records; every further variant carries its own.
			fixed += (variants.size() - 1L) * LmdbPipelinePlanCache.VARIANT_OBJECT_BYTES;
			for (LmdbPlanDecisionCache.PlanVariant variant : variants) {
				fixed += variant.challengerPosteriors().size() * LmdbPipelinePlanCache.CHALLENGER_POSTERIOR_BYTES;
				for (LmdbPlanDecisionCache.PlanVersion version : versions(variant)) {
					if (!counted.add(version.version())) {
						continue;
					}
					assertInstanceOf(LmdbPlanDecisionCache.ExactTupleRecipe.class, version.physicalRecipe())
							.accountTo(ledger);
					fixed += LmdbPipelinePlanCache.VERSION_OBJECT_BYTES;
					if (version.detachedRefreshWork() != null) {
						version.detachedRefreshWork().accountCacheIdentity(ledger);
						fixed += version.detachedRefreshWork().retainedBytes();
					}
				}
			}
			ledger.account(family.getValue().semanticDependencies());
			ledger.account(family.getKey());
			for (LmdbPlanDecisionCache.ExactInvocationKey exact : family.getValue().exactAliases().keySet()) {
				ledger.account(exact);
			}
			// Last, as publication charges them: each variant's read-log basis (its records, its log's encoding and
			// the log keys the family does not already hold).
			for (LmdbPlanDecisionCache.PlanVariant variant : variants) {
				ledger.account(variant.readLogBasis());
			}
			// The entry charge covers one exact alias; every appended one carries its own records.
			fixed += Math.max(0, family.getValue().exactAliases().size() - 1)
					* LmdbPipelinePlanCache.APPENDED_ALIAS_BYTES;
			total += fixed + ledger.bytes();
		}
		return total;
	}

	private static Sizes measure(Decision decision, int padding) {
		return measure(query("_anon_0", "urn:k0"), decision, padding);
	}

	private static Sizes measure(QueryRoot source, Decision decision, int padding) {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILY_CAPACITY, 1, 1L << 30);
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			AtomicLong reserved = new AtomicLong();
			cache.getOrComputePlan(source, context, context::revision, () -> {
				reserved.set(pendingBytes(cache));
				return computation(source, decision, padding);
			});
			assertEquals(1, cache.entryCount());
			assertTrue(reserved.get() > 0L);
			return new Sizes(cache.retainedBytes(), reserved.get());
		} finally {
			cache.close();
		}
	}

	private static TupleExpr planned(TupleExpr source, int padding) {
		source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		if (padding > 0) {
			source.setStringMetricPlanned("test.capacityPadding", "x".repeat(padding));
		}
		return source;
	}

	private static LmdbPipelinePlanCache.PlanComputation refreshable(TupleExpr source,
			LmdbPlanDecisionCache.DetachedRefreshWork refreshWork) {
		return new LmdbPipelinePlanCache.PlanComputation(planned(source, 0), decisionSummary("test-physical"),
				refreshWork);
	}

	private static PackedPlanDecisionSummary decisionSummary(String physicalFingerprint) {
		PackedPlanDecisionSummary.CostInterval interval = new PackedPlanDecisionSummary.CostInterval(1.0d, 1.0d,
				1.0d);
		return new PackedPlanDecisionSummary(physicalFingerprint, interval,
				List.of(new PackedPlanDecisionSummary.CandidateSummary(physicalFingerprint, interval)), Set.of(),
				PackedSearchCompletionStatus.EXACT_COMPLETE, PackedPlanDecisionSummary.BoundKind.VALID_LOWER_BOUND,
				1.0d, 0L, 10L, 256L);
	}

	private static LmdbPlanDecisionCache.DetachedRefreshWork refreshWork(TupleExpr template,
			LmdbPipelinePlanCache.Context refreshedContext) {
		TupleExpr detached = template.clone();
		return new LmdbPlanDecisionCache.DetachedRefreshWork() {
			@Override
			public LmdbPlanDecisionCache.RefreshComputation execute() {
				TupleExpr refreshed = detached.clone();
				refreshed.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
				LmdbPlanDecisionCache.EvidenceSnapshot evidence = LmdbPipelinePlanCache
						.evidence(refreshedContext.revision().planningRevisions());
				return new LmdbPlanDecisionCache.RefreshComputation(evidence, evidence, refreshed, "test-physical",
						new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
						new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
						LmdbPipelinePlanCache.certificate(decisionSummary("test-physical"), evidence.globalEpoch()),
						LmdbPlanDecisionCache.PlanStabilityEnvelope.exact(evidence), 1024L, 1L, true, this);
			}

			@Override
			public long retainedBytes() {
				return 0L;
			}
		};
	}

	/** P1: retained bytes are exactly the families' bytes, and retained plus in-flight bytes fit the budget. */
	private static void assertInvariant(LmdbPipelinePlanCache cache, long budget) {
		long retained = cache.retainedBytes();
		assertEquals(familyBytes(cache), retained, "retained bytes must equal the sum of the retained families");
		assertTrue(retained + pendingBytes(cache) <= budget, "retained plus in-flight bytes exceed the budget");
	}

	private static long familyBytes(LmdbPipelinePlanCache cache) {
		try {
			var familiesField = LmdbPlanDecisionCache.class.getDeclaredField("families");
			familiesField.setAccessible(true);
			Map<?, ?> families = (Map<?, ?>) familiesField.get(decisionCache(cache));
			long sum = 0L;
			for (Object family : families.values()) {
				sum += ((LmdbPlanDecisionCache.PlanFamily) family).current().get().retainedBytes();
			}
			return sum;
		} catch (ReflectiveOperationException failure) {
			throw new AssertionError("could not inspect retained families", failure);
		}
	}

	private static long pendingBytes(LmdbPipelinePlanCache cache) {
		try {
			var pendingField = LmdbPlanDecisionCache.class.getDeclaredField("pendingProviderIdentities");
			pendingField.setAccessible(true);
			return ((PackedProviderIdentityBudget) pendingField.get(decisionCache(cache))).bytes();
		} catch (ReflectiveOperationException failure) {
			throw new AssertionError("could not inspect in-flight reservations", failure);
		}
	}

	private static long misses(LmdbPipelinePlanCache cache) {
		try {
			var missesField = LmdbPipelinePlanCache.class.getDeclaredField("misses");
			missesField.setAccessible(true);
			return ((AtomicLong) missesField.get(cache)).get();
		} catch (ReflectiveOperationException failure) {
			throw new AssertionError("could not inspect flight owners", failure);
		}
	}

	private static LmdbPlanDecisionCache decisionCache(LmdbPipelinePlanCache cache) {
		try {
			var decisionCacheField = LmdbPipelinePlanCache.class.getDeclaredField("decisionCache");
			decisionCacheField.setAccessible(true);
			return (LmdbPlanDecisionCache) decisionCacheField.get(cache);
		} catch (ReflectiveOperationException failure) {
			throw new AssertionError("could not inspect the store-owned decision cache", failure);
		}
	}

	private static void awaitCompletedRefreshTasks(LmdbPipelinePlanCache cache, long expected) throws Exception {
		var executorField = LmdbPlanDecisionCache.class.getDeclaredField("refreshExecutor");
		executorField.setAccessible(true);
		ThreadPoolExecutor executor = (ThreadPoolExecutor) executorField.get(decisionCache(cache));
		long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
		while (executor.getCompletedTaskCount() < expected && System.nanoTime() < deadline) {
			Thread.onSpinWait();
		}
		assertEquals(expected, executor.getCompletedTaskCount(), "detached refresh did not complete");
	}

	private static QueryRoot query(String anonymousName, String predicate) {
		StatementPattern pattern = new StatementPattern(Var.of(anonymousName, true),
				Var.of("predicate", VF.createIRI(predicate)), Var.of("object"));
		return new QueryRoot(new Projection(pattern, new ProjectionElemList(new ProjectionElem("object"))));
	}

	private static QueryRoot languageQuery(String label, String language) {
		StatementPattern pattern = new StatementPattern(Var.of("subject"), Var.of("predicate", VF.createIRI("urn:pl")),
				Var.of("object", VF.createLiteral(label, language)));
		return new QueryRoot(new Projection(pattern, new ProjectionElemList(new ProjectionElem("subject"))));
	}

	private static LmdbPipelinePlanCache.Context context(long dataRevision) {
		LmdbEstimatorRuntime.PlanningRevisions planning = new LmdbEstimatorRuntime.PlanningRevisions(dataRevision,
				2L, 3L, 4L);
		return new LmdbPipelinePlanCache.Context(new LmdbPipelinePlanCache.Revision(planning, true), false, 0L,
				LmdbPipelinePlanCache.DatasetIdentity.of(null), LmdbPipelinePlanCache.BindingIdentity.of(null), "",
				false, false, false, "STANDARD", false);
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(5L, TimeUnit.SECONDS)) {
				throw new AssertionError("test latch was not released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while holding a cache flight", interrupted);
		}
	}
}
